    line: { color: theme.primary, width: 1 },
    rectRadius: 0.05
  });

  slide.addText("Key Insight: This metric allows direct comparison of AI capabilities across different task durations and complexity levels.", {
    x: 0.6, y: 4.55, w: 6.3, h: 0.6,
