// slide-05.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Success Probability Drops Sharply as Task Length Increases for All Models'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Success Probability Drops Sharply as Task Length Increases for All Models", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "left", valign: "middle"
  });

  // Subtle title underline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.78, w: 9.2, h: 0.03,
    fill: { color: theme.secondary }
  });

  // Figure image - main visualization (left side, larger)
  slide.addImage({
    path: "imgs/figure_3.jpg",
    x: 0.4, y: 1.0, w: 5.8, h: 3.4,
    sizing: { type: 'contain', w: 5.8, h: 3.4 }
  });

  // Key insights panel (right side)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.4, y: 1.0, w: 3.2, h: 3.4,
    fill: { color: theme.primary }
  });

  // Panel header
  slide.addText("Key Findings", {
    x: 6.5, y: 1.1, w: 3.0, h: 0.35,
    fontSize: 14, fontFace: "Arial",
    color: theme.accent, bold: true,
    align: "left", valign: "middle"
  });

  // Divider line in panel
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 1.5, w: 2.9, h: 0.02,
    fill: { color: theme.secondary }
  });

  // Insight 1
  slide.addShape(pres.shapes.OVAL, {
    x: 6.55, y: 1.7, w: 0.12, h: 0.12,
    fill: { color: theme.accent }
  });
  slide.addText("Success probability curves show sharp decline as task duration increases for all models", {
    x: 6.75, y: 1.6, w: 2.75, h: 0.6,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: false,
    align: "left", valign: "top"
  });

  // Insight 2 - Frontier models
  slide.addShape(pres.shapes.OVAL, {
    x: 6.55, y: 2.3, w: 0.12, h: 0.12,
    fill: { color: theme.accent }
  });
  slide.addText("Frontier models (Claude 3.7 Sonnet 54min, o3 1h50m) push curves far rightward vs GPT-2 (2 sec)", {
    x: 6.75, y: 2.2, w: 2.75, h: 0.65,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: false,
    align: "left", valign: "top"
  });

  // Insight 3 - Time horizon ratio
  slide.addShape(pres.shapes.OVAL, {
    x: 6.55, y: 2.95, w: 0.12, h: 0.12,
    fill: { color: theme.accent }
  });
  slide.addText("80% time horizon is ~5x shorter than 50% time horizon across all models", {
    x: 6.75, y: 2.85, w: 2.75, h: 0.55,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: false,
    align: "left", valign: "top"
  });

  // Insight 4 - Universal pattern
  slide.addShape(pres.shapes.OVAL, {
    x: 6.55, y: 3.5, w: 0.12, h: 0.12,
    fill: { color: theme.accent }
  });
  slide.addText("All models show same pattern: higher success on shorter tasks, sharply declining as duration increases", {
    x: 6.75, y: 3.4, w: 2.75, h: 0.65,
    fontSize: 11, fontFace: "Arial",
    color: "FFFFFF", bold: false,
    align: "left", valign: "top"
  });

  // Figure caption
  slide.addText("Figure 3: Per-model success probability vs task duration", {
    x: 0.4, y: 4.45, w: 5.8, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.secondary, italic: true,
    align: "center", valign: "middle"
  });

  // Model labels legend (bottom)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.8, w: 5.8, h: 0.5,
    fill: { color: theme.light, transparency: 30 }
  });

  slide.addText("GPT-2 (2 sec)", {
    x: 0.5, y: 4.85, w: 1.2, h: 0.18,
    fontSize: 9, fontFace: "Arial",
    color: theme.primary, bold: false,
    align: "left"
  });

  slide.addText("Claude 3.7 Sonnet (54 min)", {
    x: 2.0, y: 4.85, w: 1.8, h: 0.18,
    fontSize: 9, fontFace: "Arial",
    color: theme.primary, bold: false,
    align: "left"
  });

  slide.addText("o3 (1h 50min)", {
    x: 4.0, y: 4.85, w: 1.3, h: 0.18,
    fontSize: 9, fontFace: "Arial",
    color: theme.primary, bold: false,
    align: "left"
  });

  // Highlight arrow for frontier models shift
  slide.addText("Frontier models extend time horizon significantly", {
    x: 0.5, y: 5.08, w: 5.6, h: 0.18,
    fontSize: 9, fontFace: "Arial",
    color: theme.secondary, italic: true,
    align: "left"
  });

  // Page number badge (circle style)
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "FFFFFF"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

