// slide-07.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 7,
  title: 'Extrapolation Predicts Month-Long Task Automation by 2028–2031'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Extrapolation Predicts Month-Long Task Automation by 2028–2031", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.5,
    fontSize: 22, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "left", valign: "middle"
  });

  // Subtle title underline
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.78, w: 9.2, h: 0.03,
    fill: { color: theme.secondary }
  });

  // Left side: Timeline projection visual
  // Timeline background panel
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 1.0, w: 5.6, h: 3.8,
    fill: { color: theme.light, transparency: 85 }
  });

  // Timeline axis (horizontal)
  slide.addShape(pres.shapes.LINE, {
    x: 0.7, y: 4.0, w: 5.0, h: 0,
    line: { color: theme.primary, width: 2 }
  });

  // Year labels on timeline
  const years = ["2019", "2021", "2023", "2025", "2027", "2029", "2031"];
  const yearX = [0.7, 1.5, 2.3, 3.1, 3.9, 4.7, 5.5];
  years.forEach((year, i) => {
    slide.addText(year, {
      x: yearX[i] - 0.25, y: 4.05, w: 0.5, h: 0.25,
      fontSize: 9, fontFace: "Arial",
      color: theme.primary, bold: false,
      align: "center", valign: "top"
    });
    // Tick mark
    slide.addShape(pres.shapes.LINE, {
      x: yearX[i], y: 3.95, w: 0, h: 0.1,
      line: { color: theme.primary, width: 1.5 }
    });
  });

  // Data points on timeline (approximate hours for each model)
  // GPT-2 (2019): ~2 seconds = ~0.0006 hours - too small to show, use 0.01
  // GPT-3 (2020): ~10 seconds = ~0.003 hours
  // GPT-4 (2023): ~10 min = ~0.17 hours
  // Claude 3.5 (2024): ~30 min = ~0.5 hours
  // o3 (2025): ~2 hours = 2 hours
  // Target: 167 hours (1 month)

  const modelData = [
    { name: "GPT-2", year: 2019, hours: 0.0006, displayY: 3.85 },
    { name: "GPT-3", year: 2020, hours: 0.003, displayY: 3.8 },
    { name: "GPT-4", year: 2023, hours: 0.17, displayY: 3.7 },
    { name: "Claude 3.5", year: 2024, hours: 0.5, displayY: 3.6 },
    { name: "o3", year: 2025, hours: 2, displayY: 3.45 }
  ];

  // Draw historical data points and connecting line
  const xScale = (year) => 0.7 + ((year - 2019) / 12) * 5.0;
  const yScale = (hours) => 3.9 - Math.log10(hours + 0.001) * 0.35;

  // Draw connecting lines between historical points
  for (let i = 1; i < modelData.length; i++) {
    const x1 = xScale(modelData[i - 1].year);
    const x2 = xScale(modelData[i].year);
    const y1 = yScale(modelData[i - 1].hours);
    const y2 = yScale(modelData[i].hours);
    slide.addShape(pres.shapes.LINE, {
      x: x1, y: y1, w: x2 - x1, h: y2 - y1,
      line: { color: theme.secondary, width: 2 }
    });
  }

  // Draw historical points
  modelData.forEach((m) => {
    const cx = xScale(m.year);
    const cy = yScale(m.hours);
    slide.addShape(pres.shapes.OVAL, {
      x: cx - 0.08, y: cy - 0.08, w: 0.16, h: 0.16,
      fill: { color: theme.secondary }
    });
    // Label above point
    slide.addText(m.name, {
      x: cx - 0.35, y: cy - 0.35, w: 0.7, h: 0.25,
      fontSize: 8, fontFace: "Arial",
      color: theme.primary, bold: false,
      align: "center", valign: "bottom"
    });
  });

  // Projection zone (dashed line + shaded area for uncertainty)
  slide.addShape(pres.shapes.LINE, {
    x: xScale(2025), y: yScale(2), w: xScale(2030) - xScale(2025), h: yScale(167) - yScale(2),
    line: { color: theme.accent, width: 2.5, dashType: "dash" }
  });

  // 1-month horizon target zone (shaded band)
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: yScale(167) - 0.15, w: 5.3, h: 0.3,
    fill: { color: theme.accent, transparency: 60 }
  });

  // 1-month milestone marker
  slide.addShape(pres.shapes.OVAL, {
    x: 4.85, y: yScale(167) - 0.1, w: 0.2, h: 0.2,
    fill: { color: theme.accent }
  });

  // 1-month label
  slide.addText("1-month\n(167 hrs)", {
    x: 4.5, y: yScale(167) - 0.55, w: 0.9, h: 0.4,
    fontSize: 9, fontFace: "Arial",
    color: theme.accent, bold: true,
    align: "center", valign: "middle"
  });

  // Vertical line to 1-month milestone
  slide.addShape(pres.shapes.LINE, {
    x: 4.95, y: yScale(167) + 0.1, w: 0, h: 4.0 - yScale(167) - 0.1,
    line: { color: theme.accent, width: 1, dashType: "lgDash" }
  });

  // "2028–2031" range bracket
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 3.9, y: 4.35, w: 1.5, h: 0.25,
    fill: { color: theme.accent }
  });
  slide.addText("mid-2028 to mid-2031", {
    x: 3.9, y: 4.35, w: 1.5, h: 0.25,
    fontSize: 9, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "center", valign: "middle"
  });

  // Current frontier label
  slide.addText("Current: o3 ~2 hrs", {
    x: 2.9, y: 3.15, w: 1.2, h: 0.25,
    fontSize: 8, fontFace: "Arial",
    color: theme.secondary, bold: true,
    align: "center", valign: "middle"
  });

  // Growth rate annotation
  slide.addText("+20% faster growth\n2023–2025", {
    x: 2.3, y: 2.7, w: 1.0, h: 0.4,
    fontSize: 7, fontFace: "Arial",
    color: theme.light, bold: false,
    align: "center", valign: "middle"
  });

  // Right side: Key content panel
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 1.0, w: 3.4, h: 1.6,
    fill: { color: theme.primary }
  });

  slide.addText("Extrapolation", {
    x: 6.3, y: 1.1, w: 3.2, h: 0.3,
    fontSize: 13, fontFace: "Arial",
    color: theme.accent, bold: true,
    align: "left", valign: "middle"
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 1.42, w: 3.1, h: 0.015,
    fill: { color: theme.secondary }
  });

  slide.addText("If the exponential trend continues, AI reaches >1 month time horizon (167 work hours) between mid-2028 and mid-2031 — implying automation of many month-long software projects.", {
    x: 6.3, y: 1.5, w: 3.2, h: 1.0,
    fontSize: 10, fontFace: "Arial",
    color: "FFFFFF", bold: false,
    align: "left", valign: "top"
  });

  // Caveats panel
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.2, y: 2.7, w: 3.4, h: 2.1,
    fill: { color: theme.light, transparency: 30 }
  });

  slide.addText("Key Caveats", {
    x: 6.3, y: 2.8, w: 3.2, h: 0.3,
    fontSize: 13, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "left", valign: "middle"
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 3.12, w: 3.1, h: 0.015,
    fill: { color: theme.secondary }
  });

  // Caveat items with bullets
  const caveats = [
    "External validity remains an open question",
    "Tasks may not perfectly represent real-world intellectual labor",
    "Trend could slow down or speed up",
    "Supplementary experiments found little evidence trends are slower on more realistic tasks"
  ];

  caveats.forEach((caveat, i) => {
    slide.addShape(pres.shapes.OVAL, {
      x: 6.35, y: 3.28 + i * 0.38, w: 0.1, h: 0.1,
      fill: { color: theme.accent }
    });
    slide.addText(caveat, {
      x: 6.52, y: 3.18 + i * 0.38, w: 3.0, h: 0.38,
      fontSize: 9, fontFace: "Arial",
      color: theme.primary, bold: false,
      align: "left", valign: "top"
    });
  });

  // Figure caption
  slide.addText("Figure: Extrapolation of AI time horizon capabilities from GPT-2 (2019) to o3 (2025) with projected 1-month milestone", {
    x: 0.4, y: 4.75, w: 5.6, h: 0.3,
    fontSize: 9, fontFace: "Arial",
    color: theme.secondary, italic: true,
    align: "center", valign: "middle"
  });

  // Page number badge (circle style)
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "FFFFFF"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

