file.content:
/**
 * Slide 8 of 8 - Summary/Closing Page
 * Takeaways: Exponential Autonomous Capability Growth Demands Proactive Safety Governance
 */

function createSlide(pres, theme) {
  const slide = pres.addSlide();

  // Slide dimensions: 10" x 5.625" (LAYOUT_16x9)
  slide.addSlideLayout();

  // Background
  slide.background = { color: theme.bg };

  // Slide Title
  slide.addText("Takeaways: Exponential Autonomous Capability Growth Demands Proactive Safety Governance", {
    x: 0.5,
    y: 0.35,
    w: 9,
    h: 0.7,
    fontSize: 22,
    fontFace: "Arial",
    color: theme.primary,
    bold: true,
    valign: "top"
  });

  // Accent line under title
  slide.addShape("rect", {
    x: 0.5,
    y: 1.0,
    w: 9,
    h: 0.03,
    fill: { color: theme.accent }
  });

  // Key Takeaways section
  const takeaways = [
    {
      label: "Robust Metric",
      text: "50% time horizon is a robust, intuitive metric for tracking AI autonomy with R\u00B2=0.97 over 6 years of model releases"
    },
    {
      label: "Doubling Every ~7 Months",
      text: "Doubling time is ~7 months with possible acceleration since 2024"
    },
    {
      label: "Current Frontier",
      text: "Current frontier AI agents (o3) can autonomously complete tasks that take skilled humans nearly 2 hours"
    },
    {
      label: "External Validity",
      text: "External validity remains an open question \u2013 tasks may not perfectly represent real-world intellectual labor"
    },
    {
      label: "Key Limitations",
      text: "Poor performance on unstructured tasks and uncertain generalization to real-world job distributions"
    }
  ];

  const startY = 1.25;
  const rowHeight = 0.72;
  const leftColX = 0.5;
  const rightColX = 5.0;
  const labelWidth = 1.8;
  const textWidth = 3.0;

  takeaways.forEach((item, idx) => {
    const isLeftCol = idx < 3;
    const x = isLeftCol ? leftColX : rightColX;
    const row = isLeftCol ? idx : idx - 3;
    const y = startY + row * rowHeight;

    // Number badge
    slide.addShape("ellipse", {
      x: x,
      y: y + 0.05,
      w: 0.28,
      h: 0.28,
      fill: { color: theme.secondary }
    });

    slide.addText(String(idx + 1), {
      x: x,
      y: y + 0.05,
      w: 0.28,
      h: 0.28,
      fontSize: 12,
      fontFace: "Arial",
      color: theme.bg,
      bold: true,
      align: "center",
      valign: "middle"
    });

    // Label (bold)
    slide.addText(item.label, {
      x: x + 0.38,
      y: y,
      w: labelWidth,
      h: 0.35,
      fontSize: 12,
      fontFace: "Arial",
      color: theme.primary,
      bold: true,
      valign: "middle"
    });

    // Description text
    slide.addText(item.text, {
      x: x + 0.38,
      y: y + 0.32,
      w: textWidth + 0.5,
      h: 0.4,
      fontSize: 10,
      fontFace: "Arial",
      color: "595959",
      valign: "top"
    });
  });

  // Closing statement box
  slide.addShape("rect", {
    x: 0.5,
    y: 4.3,
    w: 8.6,
    h: 0.55,
    fill: { color: theme.primary }
  });

  slide.addText("The exponential growth in autonomous AI capabilities demands proactive safety governance.", {
    x: 0.5,
    y: 4.3,
    w: 8.6,
    h: 0.55,
    fontSize: 14,
    fontFace: "Arial",
    color: theme.bg,
    bold: true,
    align: "center",
    valign: "middle"
  });

  // Page number badge
  slide.addShape("ellipse", {
    x: 9.3,
    y: 5.1,
    w: 0.35,
    h: 0.35,
    fill: { color: theme.accent }
  });

  slide.addText("8", {
    x: 9.3,
    y: 5.1,
    w: 0.35,
    h: 0.35,
    fontSize: 12,
    fontFace: "Arial",
    color: theme.primary,
    bold: true,
    align: "center",
    valign: "middle"
  });

  return slide;
}

const slideConfig = {
  title: "Takeaways: Exponential Autonomous Capability Growth Demands Proactive Safety Governance",
  slideNumber: 8,
  dimensions: { width: 10, height: 5.625 }
};

module.exports = { createSlide, slideConfig };

