/**
 * Cover/Title Slide for AI Research Presentation
 * "Measuring AI Ability to Complete Long Software Tasks"
 */

function createSlide(pres, theme) {
  const slide = pres.addSlide();

  // Slide dimensions: 10" x 5.625" (LAYOUT_16x9)
  const WIDTH = 10;
  const HEIGHT = 5.625;

  // Background
  slide.background = { color: theme.bg };

  // ============================================
  // GEOMETRIC DECORATIVE ELEMENTS
  // ============================================

  // Large diagonal stripe - top right corner (accent color)
  slide.addShape("rectangle", {
    x: 7.5,
    y: -0.8,
    w: 4,
    h: 1.6,
    rotate: -25,
    fill: { color: theme.accent },
    line: { color: theme.accent, width: 0 }
  });

  // Secondary diagonal stripe - top right (secondary color, thinner)
  slide.addShape("rectangle", {
    x: 8.2,
    y: -0.5,
    w: 3,
    h: 0.5,
    rotate: -25,
    fill: { color: theme.secondary },
    line: { color: theme.secondary, width: 0 }
  });

  // Bottom left geometric accent (primary color)
  slide.addShape("rectangle", {
    x: -1,
    y: 4.8,
    w: 4,
    h: 1.2,
    rotate: -15,
    fill: { color: theme.primary },
    line: { color: theme.primary, width: 0 }
  });

  // Small accent square - bottom right area
  slide.addShape("rectangle", {
    x: 9.2,
    y: 4.6,
    w: 0.5,
    h: 0.5,
    fill: { color: theme.accent },
    line: { color: theme.accent, width: 0 }
  });

  // Small secondary square - floating
  slide.addShape("rectangle", {
    x: 8.5,
    y: 1.0,
    w: 0.25,
    h: 0.25,
    fill: { color: theme.secondary },
    line: { color: theme.secondary, width: 0 }
  });

  // ============================================
  // MAIN TITLE
  // ============================================
  slide.addText("Measuring AI Ability to Complete\nLong Software Tasks", {
    x: 0.6,
