    fontFace: "Arial",
    color: theme.accent,
    bold: true,
    align: "center",
    valign: "middle"
  });

  slide.addText("task-completion time horizon doubling every ~7 months", {
    x: 2.0,
    y: 2.72,
    w: 4.5,
    h: 1.05,
    fontSize: 18,
    fontFace: "Arial",
    color: "FFFFFF",
    bold: false,
    align: "left",
    valign: "middle"
  });

  // ============================================
  // SUBTITLE
  // ============================================
  slide.addText("Time Horizon Doubling Every 7 Months", {
    x: 0.6,
    y: 3.95,
    w: 6,
    h: 0.45,
    fontSize: 16,
    fontFace: "Arial",
    color: theme.secondary,
    bold: true,
    align: "left",
    valign: "middle"
  });

  // ============================================
  // AUTHORS & SOURCE
  // ============================================
  slide.addText("Thomas Kwa, Ben West, Joel Becker, et al. — METR", {
    x: 0.6,
    y: 4.55,
