    bold: false,
    align: "left",
    valign: "middle"
  });

  // ============================================
  // DECORATIVE VERTICAL LINE
  // ============================================
  slide.addShape("rectangle", {
    x: 6.9,
    y: 2.7,
    w: 0.04,
    h: 2.5,
    fill: { color: theme.light },
    line: { color: theme.light, width: 0 }
  });

  // Right side vertical stat
  slide.addText("AI\nProgress", {
    x: 7.1,
    y: 3.0,
    w: 1.0,
    h: 1.0,
    fontSize: 14,
    fontFace: "Arial",
    color: theme.secondary,
    bold: true,
    align: "center",
    valign: "middle"
  });

  slide.addText("2×", {
    x: 8.2,
    y: 2.85,
    w: 1.5,
    h: 0.9,
    fontSize: 44,
    fontFace: "Arial",
    color: theme.accent,
    bold: true,
    align: "center",
    valign: "middle"
  });

  slide.addText("every\n7 mo", {
    x: 7.1,
    y: 3.85,
    w: 2.6,
    h: 0.8,
    fontSize: 14,
    fontFace: "Arial",
    color: theme.primary,
    bold: false,
    align: "center",
    valign: "top"
  });

  return slide;
}

