arguments.content:
// slide-06.js
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Reasoning, Tool Use, and Error Recovery Drive Time Horizon Growth'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Slide Title
  slide.addText("Reasoning, Tool Use, and Error Recovery Drive Time Horizon Growth", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 22, fontFace: "Arial",
    color: theme.primary, bold: true,
    align: "left", valign: "middle"
  });

  // Subtitle line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.95, w: 2.5, h: 0.04,
    fill: { color: theme.secondary }
  });

  // Key Drivers section label
  slide.addText("KEY DRIVERS", {
    x: 0.5, y: 1.15, w: 3, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.secondary, bold: true
  });

  // Driver cards - 2x2 grid layout
  const drivers = [
    { icon: "brain", title: "Improved Logical Reasoning", desc: "Models can plan and execute multi-step solutions", color: theme.secondary },
    { icon: "tool", title: "Better Tool Use", desc: "Models effectively use computers, APIs, code interpreters", color: theme.accent },
    { icon: "shield", title: "Greater Reliability", desc: "Models recognize errors and self-correct", color: theme.light },
    { icon: "cycle", title: "Ability to Adapt", desc: "Models learn from failures and try alternative approaches", color: theme.secondary }
  ];

  const cardW = 4.3;
  const cardH = 0.9;
  const startX = 0.5;
  const startY = 1.5;
  const gapX = 0.2;
  const gapY = 0.15;

  drivers.forEach((driver, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = startX + col * (cardW + gapX);
    const y = startY + row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: cardW, h: cardH,
      fill: { color: "F8F9FA" },
      line: { color: "E9ECEF", width: 0.5 }
    });

    // Icon circle
    slide.addShape(pres.shapes.OVAL, {
      x: x + 0.15, y: y + 0.15, w: 0.6, h: 0.6,
      fill: { color: driver.color }
    });

    // Icon symbols inside circle
    if (driver.icon === "brain") {
      // Brain/thinking - overlapping circles
      slide.addShape(pres.shapes.OVAL, {
        x: x + 0.28, y: y + 0.32, w: 0.18, h: 0.18,
        fill: { color: theme.bg }
      });
      slide.addShape(pres.shapes.OVAL, {
        x: x + 0.38, y: y + 0.40, w: 0.16, h: 0.16,
        fill: { color: theme.bg }
      });
      slide.addShape(pres.shapes.OVAL, {
        x: x + 0.32, y: y + 0.50, w: 0.14, h: 0.14,
        fill: { color: theme.bg }
      });
    } else if (driver.icon === "tool") {
      // Tool - wrench shape (rectangle + circle)
      slide.addShape(pres.shapes.RECTANGLE, {
        x: x + 0.35, y: y + 0.38, w: 0.2, h: 0.08,
        fill: { color: theme.bg }
      });
      slide.addShape(pres.shapes.OVAL, {
        x: x + 0.30, y: y + 0.30, w: 0.15, h: 0.15,
        fill: { color: theme.bg }
      });
    } else if (driver.icon === "shield") {
      // Shield/checkmark
      slide.addShape(pres.shapes.RECTANGLE, {
        x: x + 0.35, y: y + 0.35, w: 0.2, h: 0.25,
        fill: { color: theme.bg }
      });
      slide.addText("\u2713", {
        x: x + 0.15, y: y + 0.15, w: 0.6, h: 0.6,
        fontSize: 20, fontFace: "Arial",
        color: theme.bg, align: "center", valign: "middle"
      });
    } else if (driver.icon === "cycle") {
      // Cycle/arrows - arc representation
      slide.addShape(pres.shapes.OVAL, {
        x: x + 0.30, y: y + 0.30, w: 0.35, h: 0.35,
        line: { color: theme.bg, width: 2 }
      });
      slide.addText("\u21BB", {
        x: x + 0.15, y: y + 0.15, w: 0.6, h: 0.6,
        fontSize: 22, fontFace: "Arial",
        color: theme.bg, align: "center", valign: "middle"
      });
    }

    // Driver title
    slide.addText(driver.title, {
      x: x + 0.85, y: y + 0.12, w: cardW - 1, h: 0.35,
      fontSize: 13, fontFace: "Arial",
      color: theme.primary, bold: true,
      align: "left", valign: "middle"
    });

    // Driver description
    slide.addText(driver.desc, {
      x: x + 0.85, y: y + 0.45, w: cardW - 1, h: 0.35,
      fontSize: 10, fontFace: "Arial",
      color: "6C757D",
      align: "left", valign: "top"
    });
  });

  // Key Limitation section
  const limY = 3.7;

  // Limitation label with warning indicator
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: limY, w: 9, h: 1.1,
    fill: { color: "FFF3CD" },
    line: { color: "FFECB5", width: 0.5 }
  });

  // Warning bar on left
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: limY, w: 0.08, h: 1.1,
    fill: { color: theme.light }
  });

  // Warning icon circle
  slide.addShape(pres.shapes.OVAL, {
    x: 0.7, y: limY + 0.3, w: 0.5, h: 0.5,
    fill: { color: theme.light }
  });
  slide.addText("!", {
    x: 0.7, y: limY + 0.3, w: 0.5, h: 0.5,
    fontSize: 18, fontFace: "Arial",
    color: theme.bg, bold: true,
    align: "center", valign: "middle"
  });

  // Limitation header
  slide.addText("KEY LIMITATION", {
    x: 1.35, y: limY + 0.1, w: 3, h: 0.35,
    fontSize: 11, fontFace: "Arial",
    color: "8B4513", bold: true
  });

  // Limitation content
  slide.addText([
    { text: "Performance is notably lower on less structured, \"messier\" tasks", options: { breakLine: true } },
    { text: "External validity remains an open question - tasks do not perfectly represent average real-world intellectual labor" }
  ], {
    x: 1.35, y: limY + 0.4, w: 7.8, h: 0.65,
    fontSize: 10, fontFace: "Arial",
    color: "5D4037",
    align: "left", valign: "top"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 11, fontFace: "Arial",
    color: theme.bg, bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

// Standalone preview
if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "264653",
    secondary: "2a9d8f",
    accent: "e9c46a",
    light: "f4a261",
    bg: "FFFFFF"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-06-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

