  slide.addText("KEY DRIVERS", {
    x: 0.5, y: 1.15, w: 3, h: 0.3,
    fontSize: 10, fontFace: "Arial",
    color: theme.secondary, bold: true
  });

  // Driver cards - 2x2 grid layout
  const drivers = [
    { icon: "brain", title: "Improved Logical Reasoning", desc: "Models can plan and execute multi-step solutions", color: theme.secondary },
    { icon: "tool", title: "Better Tool Use", desc: "Models effectively use computers, APIs, code interpreters", color: theme.accent },
    { icon: "shield", title: "Greater Reliability", desc: "Models recognize errors and self-correct", color: theme.light },
