    const y = startY + row * (cardH + gapY);

    // Card background
    slide.addShape(pres.shapes.RECTANGLE, {
      x: x, y: y, w: cardW, h: cardH,
      fill: { color: "F8F9FA" },
      line: { color: "E9ECEF", width: 0.5 }
    });

    // Icon circle
    slide.addShape(pres.shapes.OVAL, {
      x: x + 0.15, y: y + 0.15, w: 0.6, h: 0.6,
      fill: { color: driver.color }
    });

